#!/usr/bin/env python3
import sys

def getNumOfDigits(num: int):
    count = 1
    while True:
        count += 1
        num /= 10
        if num < 10:
            break
    return count

def solve(N: int):
    num = getNumOfDigits(N)
    if num in {1,2}:
        print(min(N,9))
    elif num in {3,4}:
        print(9 + min(N -100 + 1, 900))
    elif num in {5,6}:
        print(909 + min(N - 10000 + 1, 90000))
    else :
        print('none')
    
    return


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    solve(N)

if __name__ == '__main__':
    main()
